create extension if not exists pgcrypto;
create type public.app_role as enum ('USER','SUPER_ADMIN');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,role public.app_role not null default 'USER',created_at timestamptz not null default now());
create table public.builds(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,name text not null check(char_length(name) between 1 and 100),description text not null default '',budget numeric(12,2) not null default 0 check(budget>=0),status text not null default 'PLANNING',guest_import_key uuid unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.build_items(id uuid primary key default gen_random_uuid(),build_id uuid not null references public.builds(id) on delete cascade,category text not null,name text not null,status text not null default 'Pesquisando',priority text not null default 'Importante',planned_price numeric(12,2) not null default 0,paid_price numeric(12,2) not null default 0,target_price numeric(12,2),owned boolean not null default false,favorite boolean not null default false,technical_data jsonb not null default '{}',created_at timestamptz not null default now());
create table public.price_checks(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,build_item_id uuid references public.build_items(id) on delete set null,query text not null,source text not null,created_at timestamptz not null default now());
create table public.price_results(id uuid primary key default gen_random_uuid(),check_id uuid not null references public.price_checks(id) on delete cascade,title text not null,store text not null,price numeric(12,2) not null check(price>=0),condition text,url text not null,shipping text,match_score numeric(4,3),created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,kind text not null,title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.shared_builds(id uuid primary key default gen_random_uuid(),build_id uuid not null unique references public.builds(id) on delete cascade,slug text not null unique,enabled boolean not null default true,created_at timestamptz not null default now());
create index builds_user_idx on public.builds(user_id);create index items_build_idx on public.build_items(build_id);create index checks_user_created_idx on public.price_checks(user_id,created_at desc);create index notifications_user_created_idx on public.notifications(user_id,created_at desc);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email,display_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''));return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table public.profiles enable row level security;alter table public.builds enable row level security;alter table public.build_items enable row level security;alter table public.price_checks enable row level security;alter table public.price_results enable row level security;alter table public.notifications enable row level security;alter table public.shared_builds enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid());create policy profiles_update_self on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy builds_owner on public.builds for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy items_owner on public.build_items for all using(exists(select 1 from public.builds b where b.id=build_id and b.user_id=auth.uid())) with check(exists(select 1 from public.builds b where b.id=build_id and b.user_id=auth.uid()));
create policy checks_owner on public.price_checks for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy results_owner on public.price_results for select using(exists(select 1 from public.price_checks c where c.id=check_id and c.user_id=auth.uid()));create policy notifications_owner on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy shares_owner on public.shared_builds for all using(exists(select 1 from public.builds b where b.id=build_id and b.user_id=auth.uid())) with check(exists(select 1 from public.builds b where b.id=build_id and b.user_id=auth.uid()));
create view public.public_shared_builds with(security_invoker=true) as select s.slug,b.name,b.description,b.budget,b.status,b.created_at from public.shared_builds s join public.builds b on b.id=s.build_id where s.enabled=true;
